            new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Corneille", Text = "Le seul bruit de mon nom renverse les murailles,\nDéfait les escadrons et gaigne les batailles.", Author = "Pierre Corneille" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Corneille", Text = "Cessez de vous en plaindre, à présent le Théâtre\nEst en un point si haut que chacun l'idolâtre,\nEt ce que votre temps voyait avec mépris\nEst aujourd'hui l'amour de tous les bons esprits,\nL'entretien de Paris, le souhait des Provinces,\nLe divertissement le plus doux de nos Princes,\nLes délices du peuple, et le plaisir des grands ;\nParmi leurs passe-temps il tient les premiers rangs,\nEt ceux dont nous voyons la sagesse profonde\nPar ses illustres soins conserver tout le monde\nTrouvent dans les douceurs d'un spectacle si beau\nDe quoi se délasser d'un si pesant fardeau.", Author = "Pierre Corneille" },
