            new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Corneille", Text = "Vous me connaissez mal : la même ardeur me brûle,\nEt le désir s’accroît quand l’effet se recule.", Author = "Pierre Corneille" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Corneille", Text = "Quittez cette chimère, et m’aimez.\nJe vous aime,\nBeaucoup moins que mon Dieu, mais bien plus que moi-même.", Author = "Pierre Corneille" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Corneille", Text = "La justice n’est pas une vertu d’État.\nLe choix des actions ou mauvaises ou bonnes\nNe fait qu’anéantir la force des couronnes ;\nLe droit des rois consiste à ne rien épargner :\nLa timide équité détruit l’art de régner.\nQuand on craint d’être injuste, on a toujours à craindre ;\nEt qui veut tout pouvoir doit oser tout enfreindre,\nFuir comme un déshonneur la vertu qui le perd\nEt voler sans scrupule au crime qui lui sert.", Author = "Pierre Corneille" },
